#include "../../02-数据结构/整体二分(带修改区间第k小).cpp"
int main(){assert(range_kth({0},{}).empty());mt19937 g(125);for(int z=0;z<500;z++){int n=1+g()%30;vector<int>a(n+1);for(int i=1;i<=n;i++)a[i]=int(g()%21)-10;auto b=a;vector<Operation>ops;vector<int>exp;for(int i=0;i<100;i++){if(g()%2){int p=1+g()%n,v=int(g()%21)-10;ops.push_back({0,p,v,0});b[p]=v;}else{int l=1+g()%n,r=1+g()%n;if(l>r)swap(l,r);int k=1+g()%(r-l+1);ops.push_back({1,l,r,k});vector<int>c(b.begin()+l,b.begin()+r+1);sort(c.begin(),c.end());exp.push_back(c[k-1]);}}assert(range_kth(a,ops)==exp);}assert((range_kth({0,INT_MIN,INT_MAX},{{1,1,2,1},{0,1,INT_MAX,0},{1,1,2,2}})==vector<int>{INT_MIN,INT_MAX}));cout<<"kth OK\n";}
